%% ── Pre-computed constants ───────────────────────────────────────────────────
true_hold_x  = -0.3008;
true_hold_y  = 0.0651;
T_SS_START   = 10.0;
ss_xy_rmse   = 2.0297;
ss_z_rmse    = 0.2553;
t_peak_xy    = 1.9500;
t_peak_x     = 1.9500;
x_peak       = 24.4100;
z_margin     = 0.0250;
WIND_FX      = 0.02;
KP_POS       = 1.2;
ss_p_only_cm = 33.3333;
TAU_INT      = 4.0000;

dx = x_m - true_hold_x;
dy = y_m - true_hold_y;
x_err_cm = dx * 100;

%% ── Integral decay envelope ─────────────────────────────────────────────────
x_decay = NaN(size(T));
mask_peak = T >= t_peak_x;
x_decay(mask_peak) = x_peak * exp(-(T(mask_peak) - t_peak_x) / TAU_INT);

%% ── Trajectory phase masks ───────────────────────────────────────────────────
push_mask  = T <= t_peak_xy;
trans_mask = T > t_peak_xy & T <= T_SS_START;
ss_traj    = T >= T_SS_START;
theta_c    = linspace(0, 2*pi, 200);

%% ── Colours ──────────────────────────────────────────────────────────────────
cPush  = [1.00 0.60 0.10];  cTrans = [0.20 0.55 0.85];
cSS    = [0.25 0.72 0.38];  cSP    = [0.85 0.18 0.18];

%% ── Figure 1 — XY Trajectory ─────────────────────────────────────────────────
fig1 = figure('Name','B4 — XY Trajectory','Position',[60 60 900 1200]);
ax_traj = axes(fig1);  hold on;
if any(push_mask)
    plot(ax_traj, dx(push_mask), dy(push_mask), '-', 'Color',cPush, 'LineWidth',2.0, ...
         'DisplayName','Wind push (drift)');
end
if any(trans_mask)
    plot(ax_traj, dx(trans_mask), dy(trans_mask), '-', 'Color',[cTrans 0.7], 'LineWidth',1.8, ...
         'DisplayName','Integral correcting (return)');
end
if any(ss_traj)
    plot(ax_traj, dx(ss_traj), dy(ss_traj), '-', 'Color',[cSS 0.8], 'LineWidth',1.8, ...
         'DisplayName', sprintf('Steady state (SS RMSE=%.2f cm)', ss_xy_rmse));
end
scatter(ax_traj, 0, 0, 120, cSP, 'filled', 'DisplayName','Setpoint');
scatter(ax_traj, dx(end), dy(end), 120, cSS, 'd', 'filled', ...
        'DisplayName', sprintf('Final pos (%.1f, %.1f) cm', dx(end)*100, dy(end)*100));
plot(ax_traj, 0.05*cos(theta_c), 0.05*sin(theta_c), '--', 'Color',cSS, 'LineWidth',1.5, ...
     'DisplayName','5 cm SS acceptance boundary [Ref 4]');
ylim(ax_traj, [-0.1 0.1]);
set(ax_traj,'Box','off','XGrid','on','YGrid','on','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_traj,'\DeltaX from setpoint  (m)','FontSize',35);
ylabel(ax_traj,'\DeltaY from setpoint  (m)','FontSize',35);
title(ax_traj,'XY Trajectory (relative to setpoint)','FontSize',35);
leg1 = legend(ax_traj,'FontSize',30,'NumColumns',1);  leg1.Location='southoutside';
hold off;

%% ── Figure 2 — Altitude ──────────────────────────────────────────────────────
fig2 = figure('Name','B4 — Altitude','Position',[80 60 840 1080]);
ax_alt = axes(fig2);  hold on;
plot(ax_alt, T, z_m, '-', 'Color',[.55 .15 .75], 'LineWidth',2.0, 'DisplayName','Altitude  (m)');
patch(ax_alt, [T(1) T(end) T(end) T(1)], [0.98 0.98 1.02 1.02], cSS, ...
      'FaceAlpha',.15, 'EdgeColor','none', 'DisplayName','\pm2 cm acceptance band [Ref 3]');
yline(ax_alt, 1.0, ':', 'Color',cSS, 'LineWidth',0.8, 'HandleVisibility','off');
yline(ax_alt, 1.0+ss_z_rmse/100, '--', 'Color','red', 'LineWidth',1.0, ...
      'DisplayName', sprintf('SS RMSE=%.2f cm', ss_z_rmse));
set(ax_alt,'XLim',[0 T(end)],'YLim',[1.0-z_margin, 1.0+z_margin],'Box','off', ...
           'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_alt,'Time  (s)','FontSize',35);
ylabel(ax_alt,'Altitude  (m)','FontSize',35);
title(ax_alt,{'Altitude during Wind'; 'Lit. SS altitude error <2 cm [Ref 3]'},'FontSize',35);
leg2 = legend(ax_alt,'FontSize',30,'NumColumns',1);  leg2.Location='southoutside';
hold off;

%% ── Figure 3 — XY Error ──────────────────────────────────────────────────────
fig3 = figure('Name','B4 — XY Error','Position',[100 60 840 1200]);
ax_xy = axes(fig3);  hold on;
plot(ax_xy, T, xy_err_cm, '-',  'Color',cPush, 'LineWidth',2.0, 'DisplayName','XY error  (cm)');
yline(ax_xy, ss_xy_rmse,  '--', 'Color','red',          'LineWidth',1.0, ...
      'DisplayName', sprintf('SS RMSE=%.2f cm (PID with integral)', ss_xy_rmse));
yline(ax_xy, 5.0,         '--', 'Color',cSS,            'LineWidth',1.0, ...
      'DisplayName','5 cm SS benchmark (with integral) [Ref 4]');
yline(ax_xy, ss_p_only_cm,':', 'Color',[.55 .15 .75],  'LineWidth',1.2, ...
      'DisplayName', sprintf('P-only SS \approx%.0f cm (no integral) [Ref 1]', ss_p_only_cm));
set(ax_xy,'XLim',[0 T(end)],'YLim',[0 50],'Box','off', ...
          'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_xy,'Time  (s)','FontSize',35);
ylabel(ax_xy,'XY error  (cm)','FontSize',35);
title(ax_xy, {sprintf('XY Error under Wind (F_x=%.2f N)', WIND_FX); ...
              sprintf('Lit. SS <5 cm with integral [Ref 4] vs P-only \approx%.0f cm [Ref 1]', ss_p_only_cm)}, ...
      'FontSize',35);
leg3 = legend(ax_xy,'FontSize',30,'NumColumns',1);  leg3.Location='southoutside';
hold off;

%% ── Figure 4 — X Error + decay envelope ─────────────────────────────────────
fig4 = figure('Name','B4 — X Error','Position',[120 60 840 1080]);
ax_xerr = axes(fig4);  hold on;
plot(ax_xerr, T, x_err_cm, '-', 'Color',cTrans, 'LineWidth',2.0, 'DisplayName','X error  (cm)');
plot(ax_xerr, T, x_decay,  ':', 'Color',[.5 .5 .5], 'LineWidth',1.5, ...
     'DisplayName', sprintf('Integral decay ref (\tau=%.0f s) [Ref 2]', TAU_INT));
yline(ax_xerr, 0,          '-', 'Color','black', 'LineWidth',0.8, 'HandleVisibility','off');
yline(ax_xerr, ss_xy_rmse, '--', 'Color','red',  'LineWidth',1.0, ...
      'DisplayName', sprintf('SS RMSE=%.2f cm', ss_xy_rmse));
set(ax_xerr,'XLim',[0 T(end)],'Box','off', ...
            'YGrid','on','XGrid','off','GridAlpha',.25,'GridLineStyle','--');
xlabel(ax_xerr,'Time  (s)','FontSize',35);
ylabel(ax_xerr,'X error  (cm)','FontSize',35);
title(ax_xerr, {'X-axis Error — Outer Integral Corrects Wind'; ...
                sprintf('Decay \tau = K_p/K_i = %.0f s [Ref 1];  transient 10-30 cm [Ref 2]', TAU_INT)}, ...
      'FontSize',35);
leg4 = legend(ax_xerr,'FontSize',30,'NumColumns',1);  leg4.Location='southoutside';
hold off;
